import{_ as o}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as s,D as d,o as i,c as p,I as h,w as c,k as a,a as g,R as u,b as _,e as A}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const M=JSON.parse('{"title":"Agent 开发课程设计","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-10-07-agent-development-course-design.md","filePath":"superpowers/specs/2026-10-07-agent-development-course-design.md","lastUpdated":1791345590000}'),m={name:"superpowers/specs/2026-10-07-agent-development-course-design.md"},S=a("h1",{id:"agent-开发课程设计",tabindex:"-1"},[g("Agent 开发课程设计 "),a("a",{class:"header-anchor",href:"#agent-开发课程设计","aria-label":'Permalink to "Agent 开发课程设计"'},"​")],-1),P=u('<h2 id="_1-目标" tabindex="-1">1. 目标 <a class="header-anchor" href="#_1-目标" aria-label="Permalink to &quot;1. 目标&quot;">​</a></h2><p>将现有 <code>docs/courses/agent/</code> 下的六篇简介扩展为一套可持续查阅的 Agent 开发课程。学习者完成基础部分后，应能读懂主流 Agent 框架的关键抽象，并按顺序阅读 DeepSeek Harness 及其对照项目源码。</p><p>课程同时承担两个用途：</p><ol><li><strong>速查</strong>：通过细粒度标题快速定位概念、API、协议、设计边界与常见失败。</li><li><strong>源码学习</strong>：通过五个主线项目建立从最小 Agent Loop 到插件化 Harness 的完整理解。</li></ol><h2 id="_2-读者与学习结果" tabindex="-1">2. 读者与学习结果 <a class="header-anchor" href="#_2-读者与学习结果" aria-label="Permalink to &quot;2. 读者与学习结果&quot;">​</a></h2><p>面向已有 Python 基础编程能力，但需要系统补齐 Agent 工程的学习者。不要求事先掌握 LangChain 或任何特定供应商 SDK。Java、Python 和 TypeScript 的通用语言基础不属于本课程；阅读项目源码确实遇到语言障碍时，再回到对应语言课程单独补充。</p><p>完成后应当能够：</p><ul><li>用 Python 实现最小可观测 Agent Loop。</li><li>说清 Model、Instructions、Tools、State、Context、Session、Memory 的边界。</li><li>区分 Function Calling、MCP、Skill 和 Plugin。</li><li>设计可中断、恢复、审批和追踪的工作流。</li><li>建立现代 RAG 管线，并分别评测检索和生成。</li><li>识别无限循环、提示注入、越权工具、脏状态、重试风暴和记忆污染。</li><li>阅读 smolagents、OpenAI Agents SDK、MCP TypeScript SDK、LangGraph 和 DeepSeek Harness 的核心源码。</li></ul><h2 id="_3-信息架构" tabindex="-1">3. 信息架构 <a class="header-anchor" href="#_3-信息架构" aria-label="Permalink to &quot;3. 信息架构&quot;">​</a></h2><h3 id="_3-1-第一章-项目与知识库导航" tabindex="-1">3.1 第一章：项目与知识库导航 <a class="header-anchor" href="#_3-1-第一章-项目与知识库导航" aria-label="Permalink to &quot;3.1 第一章：项目与知识库导航&quot;">​</a></h3><p>第一章是长期维护的可点击资源库，不限于五个主线项目。资源按以下类别组织：</p><ul><li>Agent 框架与运行时。</li><li>Coding Agent 与 Harness。</li><li>MCP、Tools、Skills 与集成。</li><li>RAG、Memory 与 Context Engineering。</li><li>Workflow、Planning 与 Multi-Agent。</li><li>Evals、Tracing 与可观测性。</li><li>Browser Agent、Sandbox 与执行环境。</li><li>中英文课程、知识库、官方协议与关键论文。</li></ul><p>每条资源至少包含：</p><ul><li>项目或文章名称。</li><li>GitHub、官方文档或原文链接。</li><li>解决的问题和推荐学习内容。</li><li>需要的前置知识。</li><li>建议阅读阶段：入门、进阶或生产工程。</li><li>学习方式：通读、精读、查阅或运行实验。</li><li>推荐阅读目录或文章。</li><li>与 DeepSeek Harness 中某个概念的对应关系。</li></ul><p>资源库不复制项目 README 的宣传文字，不以 Star 数代替技术评价。易变信息标明查看日期。</p><h3 id="_3-2-基础速查章节" tabindex="-1">3.2 基础速查章节 <a class="header-anchor" href="#_3-2-基础速查章节" aria-label="Permalink to &quot;3.2 基础速查章节&quot;">​</a></h3><p>基础内容必须按认知依赖排列，支持从第 02 章开始逐篇连续阅读。每篇文章只能直接使用本篇已经解释或前序文章已经解释的术语；不可避免地引用后续主题时，必须给出一句最小说明并链接到后续文章。第一章是可随时打开的资源导航，不要求在开始基础课程前通读。</p><table><thead><tr><th>章</th><th>主题</th><th>核心范围</th></tr></thead><tbody><tr><td>02</td><td>Agent 基础</td><td>系统组成、最小闭环、停止条件、执行模式</td></tr><tr><td>03</td><td>模型与消息</td><td>Message、Role、Token、Streaming、Structured Output、Reasoning 边界</td></tr><tr><td>04</td><td>Tool Calling 与 Agent Loop</td><td>Schema、调用、结果回填、并行工具、超时、重试、幂等</td></tr><tr><td>05</td><td>State、Context、Session 与 Memory</td><td>状态所有权、持久化、恢复、压缩、短期/长期记忆</td></tr><tr><td>06</td><td>MCP</td><td>Host/Client/Server、Tools/Resources/Prompts、Transport、生命周期、授权与安全</td></tr><tr><td>07</td><td>Skills、Plugin 与 Hook</td><td>能力封装、渐进式上下文、插件生命周期、拦截与事件</td></tr><tr><td>08</td><td>RAG 与 Context Engineering</td><td>Ingestion、Chunking、Embedding、Hybrid Search、Rerank、Citation、检索评测</td></tr><tr><td>09</td><td>Workflow、Planning 与 Multi-Agent</td><td>State Machine、Plan-and-Execute、Handoff、Supervisor、中断恢复</td></tr><tr><td>10</td><td>Evals、Tracing、Guardrails 与安全</td><td>Trace、Dataset、Judge、确定性校验、权限、注入、Sandbox</td></tr></tbody></table><p>同一章内同样遵循“概念 → 最小实现 → 常用能力 → 状态与异常 → 工程边界”的顺序。课程首页和每章导读都应标明前置章节、当前学习目标和下一步，避免学习者依赖侧边栏猜测顺序。</p><h3 id="_3-3-源码精读主线" tabindex="-1">3.3 源码精读主线 <a class="header-anchor" href="#_3-3-源码精读主线" aria-label="Permalink to &quot;3.3 源码精读主线&quot;">​</a></h3><p>第十一章包含五个项目，按认知依赖排序：</p><ol><li><strong>Hugging Face smolagents</strong>：最小 Agent Loop、Tool、Code Agent、停止与执行。</li><li><strong>OpenAI Agents SDK</strong>：Agent、Runner、Handoff、Guardrail、Session 与 Tracing。</li><li><strong>MCP TypeScript SDK</strong>：Client、Server、Transport、Capability 和协议错误。</li><li><strong>LangGraph</strong>：State、Node、Edge、Checkpoint、Interrupt 与 Durable Execution。</li><li><strong>DeepSeek Harness</strong>：Agent Driver、Plugin、Session、Skill、Hook、事件系统和 Cordis。</li></ol><p>每个项目不仅提供 README 摘要，而是提供：</p><ul><li>开始前必须掌握的基础知识。</li><li>仓库结构与核心包责任。</li><li>推荐的源码阅读顺序。</li><li>重要类、函数、事件和数据结构索引。</li><li>一条可运行的最小调用链。</li><li>与其他四个项目的设计对照。</li><li>版本、开发阶段和可能的破坏性变化警告。</li></ul><h2 id="_4-文章编写契约" tabindex="-1">4. 文章编写契约 <a class="header-anchor" href="#_4-文章编写契约" aria-label="Permalink to &quot;4. 文章编写契约&quot;">​</a></h2><p>文章沿用 Java 速查笔记的可检索结构：</p><ul><li>一个概念、API、协议操作或错误边界使用一个 H3。</li><li>H3 优先使用真实 API 名或标准术语，不用“其他用法”等空泛标题。</li><li>代码前必须有一句说明“它做什么、什么时候用”。</li><li>常用用法给出小而完整的 Python 案例；不常用用法也保留独立标题和最小例子。</li><li>注释只解释关键输入、状态变化、非显然副作用、安全边界和最终输出。</li><li>输出注释单独一行，不对每行代码做机械复述。</li><li>基础概念给出专业术语、白话解释、最小案例和易混点。</li><li>不设练习题；可以使用“课后小问”形式给出带解析的概念检查。</li><li>任何安全敏感、版本敏感或容易被误解为强保证的内容，都必须明确边界。</li></ul><h2 id="_5-语言与代码策略" tabindex="-1">5. 语言与代码策略 <a class="header-anchor" href="#_5-语言与代码策略" aria-label="Permalink to &quot;5. 语言与代码策略&quot;">​</a></h2><ul><li>Agent 基础章节的正文与可运行案例统一使用 Python，包括 Agent Loop、Tool Calling、MCP、RAG、Memory、Workflow 和 Evals。</li><li>不在 Agent 课程内重复讲 Java、Python 或 TypeScript 的通用语法和标准库基础。</li><li>MCP TypeScript SDK 与 DeepSeek Harness 源码导读可以保留必要的 TypeScript 代码片段，但必须同时说明它对应的 Agent 概念；只补充读懂当前片段所需的最小说明，不扩展成 TypeScript 基础教程。</li><li>框架示例与“不依赖框架的核心机制”分开。</li><li>不为了展示 API 而引入不必要的在线服务或密钥。</li><li>可纯本地演示的状态机、检索、解析、校验和评测必须可独立运行。</li><li>必须调用模型的例子使用显式的环境变量与失败提示，不记录真实密钥。</li></ul><h2 id="_6-资源选择和更新规则" tabindex="-1">6. 资源选择和更新规则 <a class="header-anchor" href="#_6-资源选择和更新规则" aria-label="Permalink to &quot;6. 资源选择和更新规则&quot;">​</a></h2><p>资源收录优先级：</p><ol><li>协议、项目或库的官方仓库和官方文档。</li><li>有实际实现、测试、架构文档和可重现案例的活跃项目。</li><li>内容可验证、来源可追溯的课程或知识库。</li></ol><p>不收录仅有链接堆积、无法核对技术内容、过度营销或长期无维护的项目。第一章允许收录多于五个项目，但必须用“主线精读”、“专题查阅”、“案例参考”标记阅读深度。</p><h2 id="_7-导航和页面行为" tabindex="-1">7. 导航和页面行为 <a class="header-anchor" href="#_7-导航和页面行为" aria-label="Permalink to &quot;7. 导航和页面行为&quot;">​</a></h2><ul><li><code>/courses/agent/</code> 展示完整路线、章节数量和五个主线项目。</li><li>第一章必须从 Agent 首页和侧边栏的第一项直接进入。</li><li>侧边栏保持 01–11 依赖顺序，同一章内文章按数字前缀排序。</li><li>首页、侧边栏、章内上一篇/下一篇导航必须表达相同的逐篇学习顺序。</li><li>项目卡片与资源表格中的外部链接可直接点击，站内概念指向对应速查文章。</li><li>不在侧边栏为每一个外部项目展开过深层级；资源详情由第一章页面承担。</li></ul><h2 id="_8-质量门禁" tabindex="-1">8. 质量门禁 <a class="header-anchor" href="#_8-质量门禁" aria-label="Permalink to &quot;8. 质量门禁&quot;">​</a></h2><p>自动化检查至少覆盖：</p><ul><li>章节目录、Agent 首页和侧边栏的顺序一致。</li><li>每篇文章的前置概念只引用本篇或前序文章，学习顺序不存在未解释的循环依赖。</li><li>文章路径、站内链接和本地锚点存在。</li><li>第一章的资源记录包含必填字段和可访问 URL。</li><li>五个主线项目在资源库、首页和源码精读章中一致。</li><li>新文章的 H3 标题、用途说明、代码块、关键状态注释和输出契约。</li><li>代码块不包含真实凭据，危险工具操作有明确警告和权限边界。</li><li>资源库的查看日期、主线标记和项目名称可检查。</li><li>VitePress 构建成功，首页、资源导航、基础文章和五个源码页面可访问。</li></ul><h2 id="_9-非目标" tabindex="-1">9. 非目标 <a class="header-anchor" href="#_9-非目标" aria-label="Permalink to &quot;9. 非目标&quot;">​</a></h2><ul><li>不复制五个上游项目的全部 API 文档。</li><li>不将 Star 数、排行或“最好”作为稳定事实写入核心知识文章。</li><li>不在本轮实现可托管的 Agent 服务、向量数据库、模型网关或在线评测平台。</li><li>不把 Multi-Agent 宣传为默认或必然更好的方案。</li><li>不将 DeepSeek Harness 开发者预览阶段的内部接口写成永久稳定契约。</li></ul><h2 id="_10-验收标准" tabindex="-1">10. 验收标准 <a class="header-anchor" href="#_10-验收标准" aria-label="Permalink to &quot;10. 验收标准&quot;">​</a></h2><ol><li>Agent 首页呈现 01–11 完整学习路线。</li><li>第一章提供分类、可点击、有学习建议的项目与文章导航。</li><li>五个主线项目均有独立源码导读页，且 DeepSeek Harness 排在最后。</li><li>基础章节可单独速查，不依赖某个框架才能理解。</li><li>从第 02 章第一篇开始按上一篇/下一篇连续阅读时，不会先遇到尚未解释且无最小说明的基础术语。</li><li>基础章节的 Python 例子符合文章契约，可本地验证的例子全部通过；TypeScript 仅出现在对应源码导读的必要片段中。</li><li>所有站内链接、锚点、外部核心链接、侧边栏和构建通过验证。</li><li>技术审查分别给出结构/可检索性和 Agent 专业准确性结果。</li></ol>',42);function b(e,k,f,C,T,q){const n=o,r=d("ClientOnly");return i(),p("div",null,[S,h(r,null,{default:c(()=>{var t,l;return[(((t=e.$frontmatter)==null?void 0:t.aside)??!0)&&(((l=e.$frontmatter)==null?void 0:l.showArticleMetadata)??!0)?(i(),_(n,{key:0,article:e.$frontmatter},null,8,["article"])):A("",!0)]}),_:1}),P])}const H=s(m,[["render",b]]);export{M as __pageData,H as default};
